CREATE TABLE households(id INTEGER PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'America/Fortaleza');
CREATE TABLE users(id INTEGER PRIMARY KEY, household_id INTEGER NOT NULL REFERENCES households(id), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL);
CREATE TABLE sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE accounts(id INTEGER PRIMARY KEY, household_id INTEGER NOT NULL REFERENCES households(id), owner_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('checking','savings','cash')), opening_cents INTEGER NOT NULL, opening_date TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE categories(id INTEGER PRIMARY KEY, household_id INTEGER NOT NULL REFERENCES households(id), name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('income','expense')), UNIQUE(household_id,name,type));
CREATE TABLE recurring_rules(id INTEGER PRIMARY KEY, household_id INTEGER NOT NULL REFERENCES households(id), owner_id INTEGER NOT NULL REFERENCES users(id), account_id INTEGER NOT NULL REFERENCES accounts(id), category_id INTEGER NOT NULL REFERENCES categories(id), description TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), day INTEGER NOT NULL CHECK(day BETWEEN 1 AND 31), starts_on TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE transactions(id INTEGER PRIMARY KEY, household_id INTEGER NOT NULL REFERENCES households(id), owner_id INTEGER NOT NULL REFERENCES users(id), type TEXT NOT NULL CHECK(type IN ('income','expense','transfer')), description TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), expected_cents INTEGER NOT NULL CHECK(expected_cents>0), account_id INTEGER NOT NULL REFERENCES accounts(id), destination_id INTEGER REFERENCES accounts(id), category_id INTEGER REFERENCES categories(id), date TEXT NOT NULL, competence TEXT NOT NULL, due_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','paid','cancelled')), paid_date TEXT, visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','household')), recurring_rule_id INTEGER REFERENCES recurring_rules(id), version INTEGER NOT NULL DEFAULT 1, UNIQUE(recurring_rule_id,competence), CHECK(type != 'transfer' OR (destination_id IS NOT NULL AND destination_id != account_id)));
CREATE INDEX transactions_period ON transactions(household_id,competence,owner_id);
CREATE TABLE idempotency(user_id INTEGER NOT NULL REFERENCES users(id), key TEXT NOT NULL, fingerprint TEXT NOT NULL, transaction_id INTEGER NOT NULL REFERENCES transactions(id), PRIMARY KEY(user_id,key));
CREATE TABLE audit(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), entity TEXT NOT NULL, entity_id INTEGER NOT NULL, action TEXT NOT NULL, at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
PRAGMA user_version=1;
